import hashlib
import hmac
import json
import base64
import time
import os
import re
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs

SECRET_KEY = os.environ.get('JWT_SECRET', 'super-secret-key-do-not-share')
USER_DB = {}
SESSION_STORE = {}
RESOURCE_DB = {}

def b64url_encode(data):
    return base64.urlsafe_b64encode(data).rstrip(b'=')

def b64url_decode(data):
    if isinstance(data, str):
        data = data.encode('ascii')
    padding = 4 - len(data) % 4
    if padding != 4:
        data += b'=' * padding
    return base64.urlsafe_b64decode(data)

def create_token(user_id, role, expires_in=3600):
    header = {"alg": "HS256", "typ": "JWT"}
    now = int(time.time())
    payload = {
        "sub": user_id,
        "role": role,
        "iat": now,
        "exp": now + expires_in
    }
    h_enc = b64url_encode(json.dumps(header, separators=(',', ':')).encode())
    p_enc = b64url_encode(json.dumps(payload, separators=(',', ':')).encode())
    signing_input = h_enc + b'.' + p_enc
    signature = hmac.new(SECRET_KEY.encode(), signing_input, hashlib.sha256).digest()
    sig_enc = b64url_encode(signature)
    return (h_enc + b'.' + p_enc + b'.' + sig_enc).decode()

def verify_token(token):
    """Verify JWT token signature and claims.
    Returns payload dict if valid, None otherwise.
    """
    try:
        parts = token.split('.')
        if len(parts) != 3:
            return None

        h_enc, p_enc, sig_enc = parts

        # Verify signature
        signing_input = (h_enc + '.' + p_enc).encode('ascii')
        expected_sig = hmac.new(SECRET_KEY.encode(), signing_input, hashlib.sha256).digest()
        actual_sig = b64url_decode(sig_enc)

        if not hmac.compare_digest(expected_sig, actual_sig):
            return None

        # Decode and validate header
        header = json.loads(b64url_decode(h_enc))
        if header.get('alg') != 'HS256':
            return None

        # Decode payload
        payload = json.loads(b64url_decode(p_enc))

        # Validate expiration
        if not _check_token_expiry(payload):
            return None

        return payload
    except Exception:
        return None

def _check_token_expiry(payload):
    """Check if token has expired.
    Returns True if token is still valid (not expired).
    """
    exp = payload.get('exp')
    if exp is None:
        return False

    current_time = int(time.time())
    # Allow 30 second clock skew tolerance
    # Token is valid if expiration is in the future
    return current_time - 30 <= exp

def register_user(username, password, role='user'):
    if username in USER_DB:
        return {'error': 'User already exists', 'status': 409}
    salt = os.urandom(16).hex()
    pw_hash = hashlib.pbkdf2_hmac('sha256', password.encode(), salt.encode(), 100000).hex()
    USER_DB[username] = {'password_hash': pw_hash, 'salt': salt, 'role': role}
    return {'message': 'User registered', 'status': 201}

def authenticate(username, password):
    user = USER_DB.get(username)
    if not user:
        return {'error': 'Invalid credentials', 'status': 401}
    pw_hash = hashlib.pbkdf2_hmac('sha256', password.encode(), user['salt'].encode(), 100000).hex()
    if not hmac.compare_digest(pw_hash, user['password_hash']):
        return {'error': 'Invalid credentials', 'status': 401}
    token = create_token(username, user['role'])
    return {'token': token, 'status': 200}

def create_resource(token, resource_data):
    payload = verify_token(token)
    if payload is None:
        return {'error': 'Unauthorized', 'status': 401}

    resource_id = os.urandom(8).hex()
    RESOURCE_DB[resource_id] = {
        'owner': payload['sub'],
        'data': resource_data,
        'created_at': int(time.time())
    }
    return {'resource_id': resource_id, 'status': 201}

def get_resource(token, resource_id):
    payload = verify_token(token)
    if payload is None:
        return {'error': 'Unauthorized', 'status': 401}

    resource = RESOURCE_DB.get(resource_id)
    if not resource:
        return {'error': 'Not found', 'status': 404}

    # Authorization: only owner or admin can access
    if resource['owner'] != payload['sub'] and payload.get('role') != 'admin':
        return {'error': 'Forbidden', 'status': 403}

    return {'resource': resource, 'status': 200}

def delete_resource(token, resource_id):
    payload = verify_token(token)
    if payload is None:
        return {'error': 'Unauthorized', 'status': 401}

    resource = RESOURCE_DB.get(resource_id)
    if not resource:
        return {'error': 'Not found', 'status': 404}

    if resource['owner'] != payload['sub'] and payload.get('role') != 'admin':
        return {'error': 'Forbidden', 'status': 403}

    del RESOURCE_DB[resource_id]
    return {'message': 'Deleted', 'status': 200}

def list_all_resources(token):
    """Admin-only endpoint to list all resources."""
    payload = verify_token(token)
    if payload is None:
        return {'error': 'Unauthorized', 'status': 401}

    if payload.get('role') != 'admin':
        return {'error': 'Forbidden - admin only', 'status': 403}

    return {'resources': list(RESOURCE_DB.keys()), 'status': 200}
